package com.bank.java8;

import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.assertThat;

class Java21Test {

    sealed interface Instruction permits Buy, Sell {}
    record Buy(String symbol, int qty) implements Instruction {}
    record Sell(String symbol, int qty) implements Instruction {}

    String describe(Instruction i) {
        return switch (i) {                               // exhaustive over sealed type
            case Buy(String s, int q)  -> "BUY " + q + " " + s;
            case Sell(String s, int q) -> "SELL " + q + " " + s;
        };
    }

    @Test
    void patternSwitchDeconstructsRecords() {
        assertThat(describe(new Buy("RELIANCE", 100))).isEqualTo("BUY 100 RELIANCE");
        assertThat(describe(new Sell("TCS", 50))).isEqualTo("SELL 50 TCS");
    }
}
